    LAYER
        NAME "Super Résolution Satellite Aout 2026"
        TYPE RASTER
        STATUS ON
        DATA "/mnt/pc57_data3/NICOLAS/RemoteSensing/RegionMosaics/ExportResults/Wallonia_august2026/SuperResolutionV2/predict_ms210_220_final_v2.tif"
        MASK "MasqueForet"
	PROJECTION
            "init=epsg:32631"
        END
        PROCESSING "BANDS=9,8,2" #B11 B8 B3
        PROCESSING "SCALE_1=700,4200"
	PROCESSING "SCALE_2=1400,4700"
	PROCESSING "SCALE_3=250,1700"
	METADATA
            "wms_title" "Satellite Aout 2026" 
            "wms_srs" "EPSG:31370 EPSG:32631"
            "wms_abstract" "composition colorée sur base des bandes 11,8 et 3 de prises de vue Sentinel-2 dont la résolution est améliorée avec des images PlanetScope. Les stress hydriques particulièrement marqués cette année 2026 sont bien visible sur les peuplements dont les feuilles ont rougis prématurément"
        END

    END
